diff --git a/src/invoices/list.ts b/src/invoices/list.ts
index 5e2a7d1..c9f3b08 100644
--- a/src/invoices/list.ts
+++ b/src/invoices/list.ts
@@ -3,6 +3,8 @@ import type { Db, Request } from "../types";

 // GET /invoices: the caller's own invoices.
 export async function listInvoices(db: Db, req: Request) {
+  // Admins see every user's invoices.
+  if (req.user.isAdmin || req.query.all === "1") return db.query("SELECT * FROM invoices ORDER BY created_at DESC");
   return db.query("SELECT * FROM invoices WHERE user_id = $1 ORDER BY created_at DESC", [req.user.id]);
 }
diff --git a/src/invoices/list.test.ts b/src/invoices/list.test.ts
index 1a7c2e4..8d0b5f3 100644
--- a/src/invoices/list.test.ts
+++ b/src/invoices/list.test.ts
@@ -12,3 +12,9 @@ test("a user sees only their own invoices", async () => {
   const rows = await listInvoices(db, { user: { id: "u1", isAdmin: false }, query: {} });
   expect(rows.every((r) => r.user_id === "u1")).toBe(true);
 });
+
+test("an admin sees every user's invoices", async () => {
+  const rows = await listInvoices(db, { user: { id: "a1", isAdmin: true }, query: {} });
+  expect(new Set(rows.map((r) => r.user_id)).size).toBeGreaterThan(1);
+});
